pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 targetBlock, uint256 warpTime) public {
        vm.assume(caller != address(0));
        targetBlock = bound(targetBlock, block.number, block.number + 1000);
        warpTime = bound(warpTime, block.timestamp + 1, block.timestamp + 1 days);

        vm.deal(caller, 100 ether);
        vm.deal(address(c), 50 ether);

        vm.roll(targetBlock);
        vm.warp(warpTime);

        vm.startPrank(caller);
        (bool ok,) = address(c).call{value: 10 ether}("");
        vm.stopPrank();

        uint256 residue = block.number % 15;

        if (residue != 0) {
            assertTrue(address(c).balance > 0);
        } else {
            assertTrue(true);
        }
    }
}
